/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import page2020.view.Tag;import page2020.view.html5.H5a;public class B4nav extends B4list<B4nav> {	public static final String nav = "nav";	public static final String item = "nav-item";	public static final String link = "nav-link";	public static final String tab = "nav-tabs";	public static final String pill = "nav-pills";	public static final String justify = "nav-justified";	public B4nav() {		super(true);		super.data(PageKey.type, "nav");		super.cssClass(nav);	}	public B4nav(int number) {		super(true);		super.cssClass(nav);		if (number == 1) {			super.cssClass(tab);			super.data(PageKey.type, "tab");		} else if (number == 2) {			super.cssClass(pill);			super.data(PageKey.type, "pill");		}	}	public B4nav justify() {		return super.boxes().cssClass(justify);	}	public B4nav item(H5a a) {		super.box(new B4element("li").cssClass(item).append(a.cssClass(link)));		return this;	}	public B4nav item(B4dropdown dropdown) {		dropdown.setTagName("li");		dropdown.boxes().cssClass(item);		H5a a = (H5a) dropdown.find(null, "a", null);		if (a != null) {			a.cssClass(link);		}		super.box(dropdown);		return this;	}	public B4nav standalone() {		super.boxes();		int count = super.count();		for (int i=0; i < count; i++) {			Tag<?> item = (Tag<?>) super.get(i);			if (! item.hasClass(B4ctrl.active)) {				item.cssClass(B4show.D.none);			}		}		return this;	}	@Override	public B4nav active() {		if (super.getBox().getClassSet().contains(B4dropdown.dropdown)) {			((H5a) super.get(0)).cssClass(B4ctrl.active);		} else {			((H5a) super.last()).cssClass(B4ctrl.active);		}		return this;	}	@Override	public B4nav disabled() {		if (super.getBox().getClassSet().contains(B4dropdown.dropdown)) {			((H5a) super.get(0)).cssClass(B4ctrl.disabled);		} else {			((H5a) super.last()).cssClass(B4ctrl.disabled);		}		return this;	}	}